begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $native$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1744 then raise exception 'NATIVE_CAMPAIGN_CHANGED';end if;if exists(select 1 from public.campaign_state_fragments f join public.campaign_content_entries c on c.campaign_id=f.campaign_id and c.kind='equipment' and c.content_key=f.payload#>>'{catalog,contentKey}' where f.campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and f.fragment_kind='character-inventory' and c.content_key in('imported:equipment:legacy:99f2c411caadf247bd3d459a','official:equipment:es:05455ce74fdcd23b34a0c3c7','official:equipment:es:1f8f1eb126121522fd0418c5','official:equipment:es:279b82b3a270fa682c9c7463','official:equipment:es:283d43a7fbb28f2f5d081a4d','official:equipment:es:285015c1f803ed9cd52a94c8','official:equipment:es:3197a4c13048be4426d6c7a7','official:equipment:es:57bf7eb989a1861f3147626f','official:equipment:es:67c4d58203382e9febe67247','official:equipment:es:784bd660a08f0f45bc4bd35e','official:equipment:es:8e74acfe2a0c28dcf4c90bd9') and f.payload#>'{rules,definition}' is distinct from c.payload#>'{rules,definition}')then raise exception 'NATIVE_COPY_SNAPSHOT_CONFLICT';end if;
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:99f2c411caadf247bd3d459a' and md5(to_jsonb(t)::text)='5d511fa825768686302fb03c74a8418f')then raise exception 'NATIVE_DEFINITION_CHANGED:imported:equipment:legacy:99f2c411caadf247bd3d459a';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition}',$native_12ba954208bc2688${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:imported:equipment:legacy:99f2c411caadf247bd3d459a","revision":1,"language":"es","name":"Varita de Armadura de Mago","aliases":["Wand of Mage Armor"],"baseDefinitionId":null,"origin":"campaign","sources":[{"id":"original:f623ac02036ad8d63afcbd6f16d912ff93aa5bb70ede1c481206df67c2e7e8fb","kind":"legacy","title":"Varita de Armadura de Mago","language":"es","rulesEdition":null,"locator":"imported:equipment:legacy:99f2c411caadf247bd3d459a","verified":false},{"id":"original:603ec99990557cd7db93888ba28987d708c95ebd669126a02c68bd85c78263cb","kind":"legacy","title":"Wand of Mage Armor","language":"en","rulesEdition":null,"locator":"imported:equipment:eng:948605895da94b7cb6174c57","verified":false},{"id":"ece-authored-rule","kind":"campaign","title":"ECE · regla de campaña conservada","language":"es","rulesEdition":"2014","locator":"imported:equipment:legacy:99f2c411caadf247bd3d459a","verified":true}],"category":"wand","subtypes":[],"magical":true,"rarity":"uncommon","consumable":false,"properties":["magic"],"weight":{"value":0.2,"unit":"lb"},"economy":{"basePrice":null,"campaignPrice":{"quantity":2000,"unit":"gp"},"explanation":"Precio de campaña anterior conservado por separado; cero no se interpreta como precio oficial ni modifica el stock."},"description":[{"id":"campaign-text-0","section":"rules","provenance":"campaign","sourceIds":["ece-authored-rule"],"type":"paragraph","text":"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. \n Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible.\n\nLa varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro Armadura de mago sin necesidad de componentes materiales. \n Cada amanecer, la varita recupera 1d6+1 cargas gastadas, como si reordenara lentamente su estructura mágica interna.\n\nSin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes un 1 en un d20, la varita colapsa y se desintegra en polvo inerte."}],"requirements":{"attunement":true,"bearer":[],"presence":"held","explanation":"Requisitos conservados de la regla de campaña; no se añade sintonización si el texto y los campos no la exigen."},"weapon":null,"armor":null,"resources":[{"id":"cargas","name":"cargas","kind":"uses","maximum":3,"unit":"cargas","recovery":{"kind":"event","event":"dawn","explanation":"Al siguiente amanecer, no al terminar un descanso.","amount":{"kind":"roll","expression":"1d6+1"}},"exhaustion":"No se puede activar sin el recurso necesario."}],"capabilities":[{"id":"mage-armor","name":"Armadura de mago","activation":"action","trigger":"","requirements":{"attunement":true,"bearer":[],"presence":"held","explanation":"Requisitos conservados de la regla de campaña; no se añade sintonización si el texto y los campos no la exigen."},"target":"Según Armadura de mago","range":"","duration":"8 horas","concentration":false,"costs":[{"resourceId":"cargas","amount":1}],"consumeQuantity":0,"effects":[{"id":"mage-armor-0","condition":"","kind":"spell","spellKey":"mage-armor","level":1,"ability":null,"saveDc":null,"attackBonus":null,"components":"custom","explanation":"La regla de campaña exime únicamente los componentes materiales. Se conservan los demás requisitos del conjuro. La recarga no puede superar 3 cargas."},{"id":"mage-armor-1","condition":"","kind":"unmodeled","explanation":"Al gastar la última carga: tirar 1d20; con un 1 la varita se destruye. Conservar este procedimiento junto al lanzamiento.","original":{"cost":{"unit":"gp","quantity":2000},"name":"Varita de Armadura de Mago","bonus":[],"index":"wand-of-mage-armor","rarity":{"name":"Poco común","index":"uncommon"},"weight":0.2,"hasCharges":true,"properties":[],"description":"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. <br> Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible. <br><br> La varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro <u>Armadura de mago</u> sin necesidad de componentes materiales. <br> Cada amanecer, la varita recupera <u>1d6+1</u> cargas gastadas, como si reordenara lentamente su estructura mágica interna. <br><br> Sin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes <u>un 1 en un d20</u>, la varita colapsa y se desintegra en polvo inerte.","gear_category":{"url":"/api/equipment-categories/magical-accessory","name":"Accesorio mágico","index":"magical-accessory"},"chargesOptions":{"maxCharges":3,"chargeReset":"at-dawn"},"equipment_category":{"url":"/api/equipment-categories/wondrous-item","name":"Objeto maravilloso","index":"wondrous-item"},"requires_attunement":true}}],"execution":{"mode":"unsupported","handler":null,"explanation":"Regla cotejada. Falta conectar y probar su ejecución con el formato nuevo; no modifica las copias actuales.","pendingAutomation":["Aplicar y retirar los efectos al cambiar los requisitos, sin duplicar los de la copia antigua."]},"textBlockIds":["campaign-text-0"]},{"id":"last-charge-check","name":"Última carga","activation":"trigger","trigger":"Al gastar la última carga del objeto.","requirements":{"attunement":true,"bearer":[],"presence":"held","explanation":"Requisitos conservados de la regla de campaña; no se añade sintonización si el texto y los campos no la exigen."},"target":"El objeto","range":"","duration":"Instantánea","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"destroy-on-one","kind":"last-charge-destruction","condition":"Después de gastar la última carga.","sides":20,"destroyAtOrBelow":1}],"execution":{"mode":"automatic","handler":"equipment-last-charge","explanation":"Registra la comprobación pendiente y retira únicamente el ejemplar destruido al resolver el d20. La recarga queda bloqueada hasta resolverla.","pendingAutomation":[]},"textBlockIds":["campaign-text-0"]}],"recoverySourceIds":["f623ac02036ad8d63afcbd6f16d912ff93aa5bb70ede1c481206df67c2e7e8fb","603ec99990557cd7db93888ba28987d708c95ebd669126a02c68bd85c78263cb"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["Cerrar la cobertura de los datos y diferencias antiguos antes de migrar o retirar versiones; las copias y precios comerciales siguen intactos."]}}$native_12ba954208bc2688$::jsonb,true),'{features}',$native_d04fcefb0f1fc219$[{"id":"mage-armor","kind":"other","name":"Armadura de mago","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. \n Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible.\n\nLa varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro Armadura de mago sin necesidad de componentes materiales. \n Cada amanecer, la varita recupera 1d6+1 cargas gastadas, como si reordenara lentamente su estructura mágica interna.\n\nSin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes un 1 en un d20, la varita colapsa y se desintegra en polvo inerte.\n\nAl gastar la última carga: tirar 1d20; con un 1 la varita se destruye. Conservar este procedimiento junto al lanzamiento.\n\nDuración: 8 horas.\n\nCoste: 1 cargas.","showInActions":false}]$native_d04fcefb0f1fc219$::jsonb,true),'{charges}',$native_74f83a483615d8b1${"reset":"manual","current":3,"maximum":3}$native_74f83a483615d8b1$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:99f2c411caadf247bd3d459a';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:05455ce74fdcd23b34a0c3c7' and md5(to_jsonb(t)::text)='4581f4cb38412efb92b6b8af20aa1c59')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:05455ce74fdcd23b34a0c3c7';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition}',$native_235059a729a1c899${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:05455ce74fdcd23b34a0c3c7","revision":1,"language":"es","name":"Varita De Pirotecnia","aliases":[],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:2e9505dd674cc69b56cf56d5ccc5e9071e01a261777f39cdb85ef58c69320ce9","kind":"legacy","title":"Varita De Pirotecnia","language":"es","rulesEdition":null,"locator":"official:equipment:es:05455ce74fdcd23b34a0c3c7","verified":false},{"id":"original:e36c9cbc31a2aa0945da263a14c61d4112af6ad80d50371a0382031836d414c4","kind":"legacy","title":"Varita De Pirotecnia","language":"es","rulesEdition":null,"locator":"official:equipment:es:05455ce74fdcd23b34a0c3c7","verified":false},{"id":"original:d1ab4e8f597a619193c19a791bf75928a09b8352f47b3b7f8631b6e400d615e7","kind":"legacy","title":"Wand of Pyrotechnics","language":"en","rulesEdition":null,"locator":"official:equipment:eng:ae7419f38d66ce492f524adb","verified":false},{"id":"original:b2c0be1646234c504262cb86e6175198a39a53239288ae40fcf58b6004cac8ce","kind":"legacy","title":"Wand of Pyrotechnics","language":"en","rulesEdition":null,"locator":"official:equipment:eng:ae7419f38d66ce492f524adb","verified":false},{"id":"xanathar-supplied-es","kind":"book","title":"Guía de Xanathar para todo · documento español aportado por el GM","language":"es","rulesEdition":"2014","locator":"C:/Users/joaqu/Downloads/Guia de Xanathar para todo (1).pdf · página PDF 144","verified":true}],"category":"wa