if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3197a4c13048be4426d6c7a7' and md5(to_jsonb(t)::text)='a59cfe1bba990dfd85d70059b17ff822')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:3197a4c13048be4426d6c7a7';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition}',$native_1553e2ca20c2e4ce${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:3197a4c13048be4426d6c7a7","revision":1,"language":"es","name":"Bastón de Flores","aliases":[],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:491fd674d90f21e72643e44700c92c9edced219fc916c0b6761a762120bb768f","kind":"legacy","title":"Bastón de Flores","language":"es","rulesEdition":null,"locator":"official:equipment:es:3197a4c13048be4426d6c7a7","verified":false},{"id":"original:6249e2d638145c914749d792d1f8a041e0b6af0044a1a56dfacac38b96600ae5","kind":"legacy","title":"Bastón de Flores","language":"es","rulesEdition":null,"locator":"official:equipment:es:3197a4c13048be4426d6c7a7","verified":false},{"id":"original:f78f5b57668dd3a0724d75dc8e45ae3274ae74e73c172f6de4452751d81f7b58","kind":"legacy","title":"Staff of Flowers","language":"en","rulesEdition":null,"locator":"official:equipment:eng:6b4b6b3704ba3f73ff1a37d2","verified":false},{"id":"original:5b2e267e5520c9c0fed971ddbe739246c0606d55887ed0229d75a25b4e48752f","kind":"legacy","title":"Staff of Flowers","language":"en","rulesEdition":null,"locator":"official:equipment:eng:6b4b6b3704ba3f73ff1a37d2","verified":false},{"id":"xanathar-supplied-es","kind":"book","title":"Guía de Xanathar para todo · documento español aportado por el GM","language":"es","rulesEdition":"2014","locator":"C:/Users/joaqu/Downloads/Guia de Xanathar para todo (1).pdf · página PDF 141","verified":true}],"category":"staff","subtypes":[],"magical":true,"rarity":"common","consumable":false,"properties":[],"weight":null,"economy":{"basePrice":null,"campaignPrice":null,"explanation":""},"description":[{"id":"xanathar-text-0","section":"rules","provenance":"reviewed-translation","sourceIds":["xanathar-supplied-es"],"type":"paragraph","text":"Este bastón de madera tiene 10 cargas. Mientras lo sostienes, puedes usar una acción para gastar 1 carga del bastón y hacer que brote una flor de un trozo de tierra a 5 pies de ti, o del propio bastón. A menos que elijas un tipo específico de flor, el bastón crea una margarita de aroma suave. La flor es inofensiva y no mágica, y crece o se marchita como lo haría una flor normal."},{"id":"xanathar-text-1","section":"rules","provenance":"reviewed-translation","sourceIds":["xanathar-supplied-es"],"type":"paragraph","text":"El bastón recupera ld6 + 4 cargas gastadas diariamente al amanecer. Si gastas la última carga, tira un d20. En un 1, el bastón se convierte en pétalos de flores y se pierde para siempre."}],"requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"Bastón, común"},"weapon":null,"armor":null,"resources":[{"id":"item-uses","name":"Cargas","kind":"charges","maximum":10,"unit":"cargas","recovery":{"kind":"event","event":"dawn","explanation":"Recupera al amanecer, no con un descanso.","amount":{"kind":"roll","expression":"1d6+4"}},"exhaustion":"Al gastar la última carga, resolver la tirada y consecuencia indicadas en la descripción; no destruir ni transformar automáticamente."}],"capabilities":[{"id":"xanathar-property","name":"Activar propiedad","activation":"action","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"Bastón, común"},"target":"Según la descripción del objeto.","range":"","duration":"Según la descripción del objeto.","concentration":false,"costs":[{"resourceId":"item-uses","amount":1}],"consumeQuantity":0,"effects":[{"id":"xanathar-narrative","condition":"","kind":"narrative","i